let shared;export function resetBlockModels(){shared=null;}
export function loadBlockModels(){return shared??=(async()=>{const index=await fetch('./block-resources/index.json').then(checkResponse).then(r=>r.json()),own=await fetch('./block-resources/'+index.models).then(checkResponse).then(r=>r.json()),saved=await savedResources();if(!saved)return new BlockModels(own);const offset=saved.atlases.length,data={...saved.data,states:{...saved.data.states,...own.states},models:{...saved.data.models,...own.models},textures:{...saved.data.textures},pages:[...saved.data.pages,...own.pages]};for(const [id,t] of Object.entries(own.textures))data.textures[id]={...t,page:t.page+offset};const model=new BlockModels(data);model.atlases=saved.atlases;return model;})();}
